(* [comment removed for export] *)
Section ResumeCore.
Context {HCEIL : HeapCeil.HeapCeil}.
Hypothesis C : ltac2:(zQ "10!kpf$0").
Hypothesis F : ltac2:(zQ "10!kqc$0").
Variable CATCHd : ltac2:(zQ "10!kvd$0").
Variables (G' : list frame) (f g : frame) (E0 : env) (R0 : bvmap 5 word) (M00 : word -> option byte).
Let G := g :: G'.                 (* [comment removed for export] *)
Let A : Z := bv_unsigned (ev E0 0%nat).
Let Hd : Z := bv_unsigned (ev E0 2%nat).
Let spN : Z := fr_sp (lastf G CATCHd).
Hypothesis Hres : ltac2:(zQ "10!nkf@1$0?1f").
Hypothesis HINV0 : ltac2:(zQ "60!lg6!lkc!ll3!nl7!nle!hnf@6$1$5?2E0@1$3@1$4?1f@1$0$2?2R0?3M00").
Hypothesis Hch2 : forall Θ, Θ 0%nat = ev E0 0%nat -> chainT2 stof Θ M00 midP2 1152 G.
(* [comment removed for export] *)
Hypothesis Hspf : fr_sp f = A + 1152.
Hypothesis Hspg : ltac2:(zQ "60!mlc!h4!it7!mm5!nle!mn0@3$1$2@2$5@1$0?1f@1$3@1$4?1f@1$0?1g").
Hypothesis Hra : ltac2:(zQ "70!h4!l6!it7!tf!lm2!lr0!is4@3$0$2@2$6@1$1#k0@2$3?2E0Nme@1$4@1$5?1g").
Hypothesis Hsaved : ltac2:(zQ "a0!j7!h4!lsa!lu5!l6!tf!mif!mrd!nle!na>1k$0>0@2$3^1@1$7@1$8?1f@3$1@1$9@1$4#k0@2$5?2E0@2$2Nmf^2@2$6?1g^2").
Hypothesis Hcnt : ltac2:(zQ "30!mje!mrd!nle@2$0@1$1@1$2?1fNc").
Hypothesis Hlive : ltac2:(zQ "c0!j7!it2!h4!lsa!mje!lu5!l6!tf!mif!mrd!nle!na>1k$0>0@2$1@2$4@1$9@1$a?1f^1@2$5^1N8@3$2@1$b@1$6#k0@2$7?2E0@2$3Nnc^2@2$8?1g^2").
Hypothesis Hlive8 : ltac2:(zQ "d0!mje!j7!it2!h4!lsa!mj7!lu5!l6!tf!mif!mrd!nle!na>1k$1>0@2$0@1$a@1$b?1f^1>0@2$2@2$0N8^2@2$6^2Nc@3$3@1$c@1$7#k0@2$8?2E0@2$4Nh4@2$5^3N8@2$9?1g^3").
Hypothesis H27 : ev E0 27%nat = Z_to_bv 64 spN.
Hypothesis A_lo : 0x400000000000 <= A + ZLO.
Hypothesis H_low : Hd + 144 <= A + ZLO.

Theorem resume_core : forall fx : FPState,
  exists (fx' : FPState) E' R' M' t,
       first_pad isPad G = Some t
    /\ msteps EhX_ubsan.SEGS (@mkst fx R0 (Z_to_bv 64 RES_PC) M00 (seg_rom EhX_ubsan.SEGS))
                           (@mkst fx' R' (Z_to_bv 64 (pad_pc stof t)) M' (seg_rom EhX_ubsan.SEGS))
    /\ @fp_csr fx' = @fp_csr fx
    /\ regs_ok E' (PAD_regs (pad_sel t)) R' /\ know_ok EhX_ubsan.SEGS E' M' PAD_T
    /\ ev E' 34%nat = Z_to_bv 64 (fr_sp (fst t))
    /\ (forall k, (k < 12)%nat -> ev E' (slot_var k) = live (fst t) k)
    /\ ev E' 0%nat = ev E0 0%nat /\ ev E' 2%nat = ev E0 2%nat /\ ev E' 3%nat = ev E0 3%nat /\ ev E' 4%nat = ev E0 4%nat
    /\ ev E' 27%nat = Z_to_bv 64 spN
    /\ (forall a : word, ~ (A + ZLO <= bv_unsigned a < A + 1152) -> ~ (Hd <= bv_unsigned a < Hd + 144) -> M' a = M00 a)
